	private static TupleExpr compareOriginalEvents(Fixture fixture, TupleExpr root, BindingSet optimizationInput,
			BindingSet input, boolean typed) {
		List<BindingSet> expected = ordinaryRows(fixture, root.clone(), input);
		TupleExpr optimized = fixture.strategy.optimize(root, fixture.statistics, optimizationInput);
		List<BindingSet> optimizedReference = ordinaryRows(fixture, optimized.clone(), input);
		assertEquals(values(expected), values(optimizedReference),
				"optimizer preserves the original exact value/domain bag");
		assertEquals(events(expected), events(optimizedReference),
				"optimizer preserves the original tested row events");
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(org.eclipse.rdf4j.query.algebra.QueryModelNode node) {
				if (node instanceof TupleExpr tuple) {
					tuple.setExecutionSummaryEnabled(true);
				}
				super.meetNode(node);
			}
		});
		List<BindingSet> actual = drain(fixture.strategy.precompile(optimized), input, typed);
		assertEquals(values(expected), values(actual), "exact visible values including present-null domain");
		assertEquals(events(expected), events(actual), "original tracked/LOCAL/REQUEST/GRAPH events before capability");
		for (BindingSet row : actual) {
			BindingSetOrigin.of(row).retainedParametersForTransport().forEach((name, value) -> {
				Value supplied = BindingSetOrigin.of(input).retainedParametersForTransport().get(name);
				if (supplied != null)
					assertSame(supplied, value, "retained caller representative");
			});
			GraphFrameBindings.from(row).retainedParametersForTransport().forEach((name, value) -> {
				Value supplied = GraphFrameBindings.from(input).retainedParametersForTransport().get(name);
				if (supplied != null)
					assertSame(supplied, value, "retained GRAPH representative");
			});
		}
		return optimized;
	}

	private static void assertCompleteOwner(TupleExpr root, TestReporter reporter) {
		TupleExpr node = root;
		while (node instanceof UnaryTupleOperator unary && !(node instanceof Projection))
			node = unary.getArg();
		assertTrue(node instanceof Projection, "the real output Projection remains the owner");
		TupleExpr body = ((Projection) node).getArg();
		String plan = body.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
		String path = body.getStringMetricActual("nativeExecutionPath");
		reporter.publishEntry(Map.of("bodyPlan", String.valueOf(plan), "bodyActualPath", String.valueOf(path)));
		assertNotNull(plan, "the complete body capability is planned after semantic assertions");
		assertTrue(plan.contains("SealedProjection("),
				"fresh total aliases must preserve the complete native body capability");
		assertNotNull(path, "a candidate alone is not an actual completed-body witness");
		assertFalse(path.contains(LmdbNativeAttemptMetrics.PATH_GENERIC_FALLBACK));
		// The strategy remains naturally selected. No irKernel/batch/factor winner is forced or asserted.
	}

	private static void assertPlannedCompleteOwner(TupleExpr root) {
		TupleExpr node = root;
		while (node instanceof UnaryTupleOperator unary && !(node instanceof Projection))
			node = unary.getArg();
		assertTrue(node instanceof Projection, "the real output Projection remains the owner");
		String plan = ((Projection) node).getArg().getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
		assertNotNull(plan, "the runtime null-frame case must use a genuinely compiled sealed owner");
		assertTrue(plan.contains("SealedProjection("), "the same run must reach the owning runtime guard");
	}

	private static void assertSurvivingAssignment(TupleExpr root) {
		int[] assignments = { 0 };
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Extension extension) {
				assignments[0] += extension.getElements().size();
				super.meet(extension);
			}
		});
		assertTrue(assignments[0] > 0,
				"fixture hit: a real Extension must survive optimization before claiming the alias red");
	}

	private static String query(boolean distinct, boolean alias, boolean chain, boolean outside) {
		String select = "?root ?name " + (alias ? "?label " : "") + (chain ? "?label2 " : "") + "?edge ?kind";
		String bind = alias ? " BIND(?name AS ?label) " + (chain ? "BIND(?label AS ?label2) " : "") : "";
		return PREFIX + "SELECT " + (distinct ? "DISTINCT " : "") + select + " WHERE { "
				+ "{ ?root a ex:T } UNION { ?root a ex:U } OPTIONAL { ?root ex:name ?name . "
				+ (outside ? "" : bind) + " } " + (outside ? bind : "")
				+ " OPTIONAL { ?root ex:link ?edge . OPTIONAL { ?edge ex:kind ?kind } } }";
	}

	private static List<BindingSet> ordinaryRows(Fixture fixture, TupleExpr root, BindingSet input) {
		var ordinary = new DefaultEvaluationStrategy(fixture.source, (FederatedServiceResolver) null);
		ordinary.setQueryExecutionPolicy(fixture.store.getQueryExecutionPolicy());
		return drain(ordinary.precompile(root), input, false);
	}

	private static List<BindingSet> drain(QueryEvaluationStep step, BindingSet input, boolean typed) {
		if (!typed)
			try (var rows = step.evaluate(input)) {
				return QueryResults.asList(rows);
			}
		List<BindingSet> result = new ArrayList<>();
		try (var rows = NativeResultSteps.open(step, input)) {
			for (NativeResultRow row; (row = rows.next()) != null;)
				result.add(row.toBindingSet());
		}
		return result;
	}

	private static List<BindingSet> publicRows(SailRepository repository, String query) {
		try (var connection = repository.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			return QueryResults.asList(rows);
		}
	}

	private record Events(Map<String, Value> values, Set<String> names, boolean tracked, Set<String> locals,
			Set<String> requests, Map<String, Value> parameters, Map<String, Value> graphs) {
	}

	private static Map<Events, Integer> events(List<BindingSet> rows) {
		Map<Events, Integer> result = new LinkedHashMap<>();
		for (BindingSet row : rows) {
			var origin = BindingSetOrigin.of(row);
			result.merge(
					new Events(mapping(row), Set.copyOf(row.getBindingNames()), BindingSetOrigin.isTrackedInput(row),
							origin.localNames(), origin.requestNames(), origin.retainedParametersForTransport(),
							GraphFrameBindings.from(row).retainedParametersForTransport()),
					1, Integer::sum);
		}
		return result;
	}

	private static Map<Map<String, Value>, Integer> values(List<BindingSet> rows) {
		Map<Map<String, Value>, Integer> result = new LinkedHashMap<>();
		for (BindingSet row : rows)
			result.merge(mapping(row), 1, Integer::sum);
		return result;
	}

	private static Map<String, Value> mapping(BindingSet row) {
		Map<String, Value> result = new LinkedHashMap<>();
		for (String name : row.getBindingNames())
			if (row.hasBinding(name))
				result.put(name, row.getValue(name));
		return Collections.unmodifiableMap(result); // Map.copyOf would erase the supported null-domain fixture via an
													// exception.
	}

	private static Map<Map<String, Value>, Integer> expected(boolean distinct, boolean alias, boolean chain) {
		Map<Map<String, Value>, Integer> result = new LinkedHashMap<>();
		for (String name : List.of("A", "B", "C")) {
			Map<String, Value> row = new LinkedHashMap<>();
			row.put("root", iri(name.equals("C") ? "c" : "a"));
			row.put("name", VF.createLiteral(name));
			if (alias)
				row.put("label", VF.createLiteral(name));
			if (chain)
				row.put("label2", VF.createLiteral(name));
			row.put("edge", iri(name.equals("C") ? "e3" : "e1"));
			if (!name.equals("C"))
				row.put("kind", VF.createLiteral("K1"));
			result.put(Collections.unmodifiableMap(row), distinct || name.equals("C") ? 1 : 2);
		}
		result.put(Map.of("root", iri("b")), 1);
		return result;
	}

	private static BindingSet input(String shape) {
		QueryBindingSet row = new QueryBindingSet();
		if (shape.equals("PRESENT_NULL")) {
			row.setBinding("label", null);
			assertTrue(row.hasBinding("label"));
			return row;
		}
		if (shape.equals("GRAPH_HIDDEN")) {
			var supplied = GraphFrameBindings.supply(row, "privateGraph", iri("graph"));
			var hidden = GraphFrameBindings.preserve(supplied, new QueryBindingSet());
			assertTrue(hidden.isEmpty());
			assertFalse(GraphFrameBindings.from(hidden).retainedParametersForTransport().isEmpty());
			return hidden;
		}
		if (shape.equals("REQUEST_ABSENT")) {
			row.setBinding("label", VF.createLiteral("caller"));
			QueryBindingSet request = new QueryBindingSet(BindingSetOrigin.requestInput(row));
			request.removeBinding("label");
			assertTrue(BindingSetOrigin.of(request).isRequest("label"));
			return request;
		}
		var origin = BindingSetOrigin.of(EmptyBindingSet.getInstance());
		return BindingSetOrigin.with(row, shape.equals("LOCAL_ABSENT") ? origin.producing(Set.of("label")) : origin);
	}

	private static IRI iri(String local) {
		return VF.createIRI(NS + local);
	}

	private static final class Fixture implements AutoCloseable {
		final LmdbStore store;
		final SailRepository lmdb, memory = new SailRepository(new MemoryStore());
		SailDataset dataset;
		SailDatasetTripleTermSource source;
		org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics statistics;
		LmdbNativeEvaluationStrategy strategy;

		Fixture(Path directory) throws InterruptedException {
			// Deliberately overlay-off functional control; not a claim of benchmark @Fork/setup equivalence.
			var config = new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
					.setDirectAdjacencyEnabled(true)
					.setValueOverlayEnabled(false);
			config.setExperimentalQueryOptimizations(true);
			config.setSketchEstimatorEnabled(false);
			store = new LmdbStore(directory.toFile(), config);
			lmdb = new SailRepository(store);
			try {
				lmdb.init();
				memory.init();
				List<Statement> data = List.of(VF.createStatement(iri("a"), RDF.TYPE, iri("T")),
						VF.createStatement(iri("a"), RDF.TYPE, iri("U")),
						VF.createStatement(iri("b"), RDF.TYPE, iri("T")),
						VF.createStatement(iri("c"), RDF.TYPE, iri("U")),
						VF.createStatement(iri("a"), iri("name"), VF.createLiteral("A")),
						VF.createStatement(iri("a"), iri("name"), VF.createLiteral("B")),
						VF.createStatement(iri("c"), iri("name"), VF.createLiteral("C")),
						VF.createStatement(iri("a"), iri("link"), iri("e1")),
						VF.createStatement(iri("c"), iri("link"), iri("e3")),
						VF.createStatement(iri("e1"), iri("kind"), VF.createLiteral("K1")));
				for (var repository : List.of(lmdb, memory))
					try (var connection = repository.getConnection()) {
						connection.begin();
						for (Statement statement : data)
							connection.add(statement);
						connection.commit();
					}
				assertTrue(store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS),
						"functional adjacency readiness, not a speed assertion");
				dataset = NativeQuerySourceAccess.openExplicitDataset(store);
				source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				statistics = NativeQuerySourceAccess.evaluationStatistics(store);
				strategy = (LmdbNativeEvaluationStrategy) NativeQuerySourceAccess.evaluationStrategy(store, source,
						statistics);
			} catch (InterruptedException | RuntimeException | Error failure) {
				if (failure instanceof InterruptedException)
					Thread.currentThread().interrupt();
				try {
					close();
				} catch (RuntimeException | Error cleanup) {
					failure.addSuppressed(cleanup);
				}
				throw failure;
			}
		}

		@Override
		public void close() {
			try {
				if (dataset != null)
					dataset.close();
			} finally {
				try {
					lmdb.shutDown();
				} finally {
					memory.shutDown();
				}
			}
		}
	}

	private static final class AutoProperties implements AutoCloseable {
		private final Map<String, String> previous = new LinkedHashMap<>();

		AutoProperties() {
			for (String flag : AUTO_FLAGS)
				set(flag, null);
			set("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
			set("rdf4j.lmdb.janinoCodegen.synchronous", "true");
			set("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		}

		private void set(String key, String value) {
			previous.put(key, System.getProperty(key));
			if (value == null)
				System.clearProperty(key);
			else
				System.setProperty(key, value);
		}

		@Override
		public void close() {
			previous.forEach((key, value) -> {
				if (value == null)
					System.clearProperty(key);
				else
					System.setProperty(key, value);
			});
		}
	}
